+  function makeProxy(value: any, root: string, parts: string[], leaves: Map<string, Leaf>): any {
+    if (!isObject(value)) return value
+    const record = (nextParts: string[], nextValue: any) => {
+      const path = [root, ...nextParts].join('.')
+      leaves.set(path, { root, parts: nextParts, value: nextValue })
+    }
+    return new Proxy(value, {
+      get(target, property, receiver) {
+        if (typeof property === 'symbol') return Reflect.get(target, property, receiver)
+        const key = String(property)
+        if (target instanceof Map) {
+          if (key === 'get') return (mapKey: any) => {
+            const nextParts = [...parts, `map:${String(mapKey)}`]
+            const result = target.get(mapKey)
+            record(nextParts, result)
+            return makeProxy(result, root, nextParts, leaves)
+          }
+          if (key === 'has') return (mapKey: any) => {
+            const nextParts = [...parts, `map:${String(mapKey)}`]
+            const result = target.has(mapKey)
+            record(nextParts, result)
+            return result
+          }
+          return Reflect.get(target, property, target)
+        }
+        if (target instanceof Set) {
+          if (key === 'has') return (setValue: any) => {
+            const nextParts = [...parts, `set:${String(setValue)}`]
+            const result = target.has(setValue)
+            record(nextParts, result)
+            return result
+          }
+          return Reflect.get(target, property, target)
+        }
+        if (Array.isArray(target) && key === 'includes') {
+          return (...args: any[]) => {
